12	 * incoming number once, then relies on {@link #canonicalize(String)} to compare it against
13	 * existing owners regardless of how those numbers were originally formatted.
14	 */
15	@Component
16	public class TelephoneNormalizer {
17	
18	    /** Assumed country code (with '+') for numbers submitted without an explicit country code. */
19	    private static final String DEFAULT_COUNTRY_CODE = "+61";
20	
21	    /** Minimum number of digits after the leading '+' for a valid E.164 number. */
22	    private static final int MIN_DIGITS = 8;
23	
24	    /** Maximum number of digits after the leading '+' for a valid E.164 number. */
25	    private static final int MAX_DIGITS = 15;
26	
27	    /**
28	     * Normalizes a telephone number submitted to the create endpoint into E.164 form: a leading
29	     * '+' and country code are kept when present, otherwise the country code {@code +61} is assumed
30	     * and a single leading '0' is dropped from the national digits; spaces, dashes and brackets are
31	     * stripped. The result must carry 8 to 15 digits after the '+'; otherwise the submission is
32	     * rejected as a 400 (via {@link InvalidOwnerFieldsException}, which the
33	     * {@code ExceptionControllerAdvice} renders with {@code telephone} in its {@code errors} array).
34	     * For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
35	     *
36	     * @param telephone the raw telephone value from the request
37	     * @return the canonical E.164 telephone to store and return
38	     * @throws InvalidOwnerFieldsException if the value cannot form a valid E.164 number
39	     */
40	    public String normalize(String telephone) {
41	        String e164 = canonicalize(telephone);
42	        int digitCount = e164.length() - 1;
43	        if (!e164.startsWith("+") || digitCount < MIN_DIGITS || digitCount > MAX_DIGITS) {
44	            throw new InvalidOwnerFieldsException(List.of("telephone"));
45	        }
46	        return e164;
47	    }
48	
49	    /**
50	     * Reduces an arbitrary telephone (possibly {@code null} or differently formatted) to the
51	     * canonical E.164 comparison form, so numbers that differ only in formatting still collide.
52	     * A leading '+' and country code are kept when present; otherwise the country code {@code +61}
53	     * is assumed and a single leading '0' is dropped from the national digits. Spaces, dashes,
54	     * brackets and any other non-digit characters are stripped. Unlike {@link #normalize(String)}
55	     * this never rejects its input (it does not enforce the digit-count rule); it is applied to
56	     * existing owners' stored telephones during duplicate detection.
57	     *
58	     * @param telephone a stored or submitted telephone, or {@code null}
59	     * @return the telephone reduced to its canonical E.164 comparison form
60	     */
61	    public String canonicalize(String telephone) {
62	        if (telephone == null) {
63	            return "";
64	        }
65	        boolean hasCountryCode = telephone.trim().startsWith("+");
66	        String digits = telephone.replaceAll("\\D", "");
67	        if (!hasCountryCode) {
68	            if (digits.startsWith("0")) {
69	                digits = digits.substring(1);
70	            }
71	            digits = DEFAULT_COUNTRY_CODE.substring(1) + digits;
72	        }
73	        return "+" + digits;
74	    }
75	}
