61	    /**
62	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
63	     * class.
64	     *
65	     * @param e     Object referring to the thrown exception.
66	     * @param status HTTP response status.
67	     * @param url URL request.
68	     */
69	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
70	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
71	        problemDetail.setType(URI.create(url.toString()));
72	        problemDetail.setTitle(e.getClass().getSimpleName());
73	        problemDetail.setDetail(detail);
74	        problemDetail.setProperty("timestamp", Instant.now());
75	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
76	        return problemDetail;
77	    }
78	
79	    /**
80	     * Builds a 409 Conflict response for a create request that collides with an existing owner. The
81	     * body is a {@link ProblemDetail} carrying {@code detail} and an {@code errors} array naming the
82	     * conflicting fields, matching the shape produced for the other owner-creation error responses.
83	     *
84	     * @param e Object referring to the thrown exception.
85	     * @param request {@link HttpServletRequest} object referring to the current request.
86	     * @param detail the human-readable detail message.
87	     * @param errors the names of the fields whose values conflicted.
88	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
89	     */
90	    private ResponseEntity<ProblemDetail> conflict(Exception e, HttpServletRequest request, String detail, List<String> errors) {
91	        HttpStatus status = HttpStatus.CONFLICT;
92	        ProblemDetail problemDetail = this.detailBuild(e, status, request.getRequestURL(), detail);
93	        problemDetail.setProperty("errors", errors);
94	        return ResponseEntity.status(status).body(problemDetail);
95	    }
