113	     *
114	     * @param e The {@link Exception} to be handled
115	     * @param request {@link HttpServletRequest} object referring to the current request.
116	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
117	     */
118	    @ExceptionHandler(Exception.class)
119	    @ResponseBody
120	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
121	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
122	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
123	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
124	        return ResponseEntity.status(status).body(detail);
125	    }
