133	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
134	     */
135	    @ExceptionHandler(DataIntegrityViolationException.class)
136	    @ResponseBody
137	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
138	        logger.warn("Data integrity violation at {} {}: {}",
139	            request.getMethod(),
140	            request.getRequestURI(),
141	            e.getMessage());
142	        logger.debug("Data integrity violation stacktrace", e);
143	        HttpStatus status = HttpStatus.NOT_FOUND;
144	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
145	        return ResponseEntity.status(status).body(detail);
146	    }
