1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
22	    @Mapping(target = "initials", expression = "java(owner.getFirstName().substring(0, 1).toUpperCase() + \".\" + owner.getLastName().substring(0, 1).toUpperCase() + \".\")")
23	    @Mapping(target = "membershipNumber", expression = "java(membershipNumber(owner))")
24	    @Mapping(target = "membershipTier", expression = "java(membershipTier(owner))")
25	    @Mapping(target = "locality", expression = "java(locality(owner))")
26	    OwnerDto toOwnerDto(Owner owner);
27	
28	    /**
29	     * Derives the owner's {@code locality} from the {@code city} using a fixed city-to-region
30	     * table ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns
31	     * the canonical region string, or {@code UNKNOWN} when the city is absent or not in the table.
32	     *
33	     * @param owner the owner being mapped
34	     * @return the derived locality
35	     */
36	    default String locality(Owner owner) {
37	        String city = owner.getCity();
38	        if ("Sydney".equals(city)) {
39	            return "NSW";
40	        }
41	        if ("Melbourne".equals(city)) {
42	            return "VIC";
43	        }
44	        if ("Brisbane".equals(city)) {
45	            return "QLD";
46	        }
47	        return "UNKNOWN";
48	    }
49	
50	    /**
51	     * Derives the owner's {@code membershipTier}. Returns {@code SILVER} when the owner's
52	     * {@code namesakeCount} is {@code 0} and an email is present, otherwise {@code BRONZE}.
53	     *
54	     * @param owner the owner being mapped
55	     * @return the derived membership tier
56	     */
57	    default OwnerDto.MembershipTierEnum membershipTier(Owner owner) {
58	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
59	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
60	        return uniqueName && hasEmail ? OwnerDto.MembershipTierEnum.SILVER : OwnerDto.MembershipTierEnum.BRONZE;
61	    }
62	
63	    /**
64	     * Builds the owner's {@code membershipNumber}, formatted {@code '<customerCode>-M<YY>'},
65	     * where {@code YY} is the last two digits of the {@code registrationDate} year (e.g.
66	     * {@code 'MEL-SMI-0007-M26'}). Returns {@code null} when either the customer code or the
67	     * registration date is absent.
68	     *
69	     * @param owner the owner being mapped
70	     * @return the formatted membership number, or {@code null} when it cannot be derived
71	     */
72	    default String membershipNumber(Owner owner) {
73	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
74	            return null;
75	        }
76	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
77	    }
78	
79	    Owner toOwner(OwnerDto ownerDto);
80	
81	    @Mapping(target = "id", ignore = true)
82	    @Mapping(target = "pets", ignore = true)
83	    Owner toOwner(OwnerFieldsDto ownerDto);
84	
85	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
86	
87	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
88	
89	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
90	        OwnerPageDto ownerPageDto = new OwnerPageDto();
91	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
92	        ownerPageDto.setPage(ownerPage.getNumber());
93	        ownerPageDto.setSize(ownerPage.getSize());
94	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
95	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
96	        return ownerPageDto;
97	    }
98	}
